import React, { useState } from 'react';

export default function AdminLoginModal({ adminToken, setAdminToken, adminInfo, setAdminInfo }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = () => {
    setError('');
    // This is a mock login. In a real app, you'd call a backend API.
    // قم بتغيير كلمة المرور هنا إلى كلمة مرور قوية خاصة بك
    const mySecretUsername = 'admin';
    const mySecretPassword = 'MyStrongPass2025'; 
    if (username === mySecretUsername && password === mySecretPassword) { 
      const token = 'dummy-token-' + Date.now();
      setAdminToken(token);
      setAdminInfo({ name: 'المدير' });
      // Close the modal programmatically after successful login
      const modalEl = document.getElementById('adminLoginModal');
      if (modalEl) {
        const modalInstance = window.bootstrap.Modal.getInstance(modalEl);
        if (modalInstance) {
          modalInstance.hide();
        }
        const closeBtn = modalEl.querySelector('.btn-close');
        if (closeBtn) closeBtn.click();
      }
      setUsername('');
      setPassword('');
    } else {
      alert('اسم المستخدم أو كلمة المرور غير صحيحة');
      setError('اسم المستخدم أو كلمة المرور غير صحيحة');
    }
  };

  const handleLogout = () => {
    setAdminToken('');
    setAdminInfo(null);
    localStorage.removeItem('adminToken');
    // Also close the modal
    const modalEl = document.getElementById('adminLoginModal');
    if (modalEl) {
        const modalInstance = window.bootstrap.Modal.getInstance(modalEl);
        if (modalInstance) {
          modalInstance.hide();
        }
        const closeBtn = modalEl.querySelector('.btn-close');
        if (closeBtn) closeBtn.click();
    }
  };

  return (
    <div className="modal fade" id="adminLoginModal" tabIndex="-1" aria-labelledby="adminLoginModalLabel" aria-hidden="true">
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content zoom-in">
          <div className="modal-header">
            <h5 className="modal-title" id="adminLoginModalLabel">لوحة تحكم المسؤول</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            {adminToken ? (
              <div className="text-center">
                <p className="mb-4">مرحباً بك، {adminInfo?.name || 'المسؤول'}</p>
                <button className="btn btn-danger w-100" onClick={handleLogout}>تسجيل الخروج</button>
              </div>
            ) : (
              <div>
                <div className="mb-3">
                  <label htmlFor="adminUsername" className="form-label">اسم المستخدم</label>
                  <input 
                    type="text" 
                    className="form-control" 
                    id="adminUsername"
                    value={username} 
                    onChange={(e) => setUsername(e.target.value)}
                    placeholder="أدخل اسم المستخدم"
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="adminPassword" className="form-label">كلمة المرور</label>
                  <input 
                    type="password" 
                    className="form-control" 
                    id="adminPassword"
                    value={password} 
                    onChange={(e) => setPassword(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
                    placeholder="أدخل كلمة المرور"
                  />
                  <small className="text-muted">للتجربة: admin / MyStrongPass2025</small>
                  {error && <div className="alert alert-danger mt-2 py-1 small">{error}</div>}
                </div>
                <button className="btn btn-primary w-100" onClick={handleLogin}>دخول</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
